#[tokio::test]
async fn helix_matches_states_captured_from_helix_25_07_1() {
    for case in CAPTURED_HELIX {
        let file = if case.path.is_empty() {
            Some("fixture.txt".to_string())
        } else {
            Some(case.path.to_string())
        };
        let mut harness = EditorHarness::with_config_and_size(
            Buffer::new(file, case.text.to_string()),
            helix_config(),
            100,
            24,
        );
        press_sequence(&mut harness, case.keys).await;
        assert_eq!(mode_name(harness.mode()), case.mode, "{}", case.id);
        assert_eq!(harness.buffer_contents(), case.text_after, "{}", case.id);
        if !case.check_ranges {
            continue;
        }
        let (primary, ranges) = harness.editor.test_felix_ranges();
        assert_eq!(Some(primary), case.primary, "{}", case.id);
        assert_eq!(ranges.as_slice(), case.ranges, "{}", case.id);
    }
}
